<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { Cloud,RefreshCw,Save } from 'lucide-vue-next'
import { useAuthStore } from '@/stores/useAuthStore'
const auth=useAuthStore(); const config=ref<any>({configured:false}); const provider=ref<'aliyun'|'tencent'|'aws'|'huawei'|'openstack'>('aliyun'); const instances=ref<any[]>([]); const schedule=ref({enabled:false,intervalMinutes:60,nextSyncAt:'',lastSyncAt:'',lastSyncStatus:'',lastSyncMessage:'',lastSyncCount:0}); const showForm=ref(false); const busy=ref(false); const message=ref(''); const error=ref('')
const form=ref({provider:'aliyun' as 'aliyun'|'tencent'|'aws'|'huawei'|'openstack',endpoint:'ecs.aliyuncs.com',regionId:'cn-hangzhou',projectId:'',projectName:'',userDomain:'Default',projectDomain:'Default',accessKeyId:'',accessKeySecret:'',insecure:true,enabled:true})
function endpointFor(value:'aliyun'|'tencent'|'aws'|'huawei'|'openstack'){return value==='tencent'?'cvm.tencentcloudapi.com':value==='aws'?'ec2.us-east-1.amazonaws.com':value==='huawei'?'ecs.cn-north-4.myhuaweicloud.com':value==='openstack'?'https://keystone.example.com':'ecs.aliyuncs.com'}
function regionFor(value:'aliyun'|'tencent'|'aws'|'huawei'|'openstack'){return value==='tencent'?'ap-guangzhou':value==='aws'?'us-east-1':value==='huawei'?'cn-north-4':value==='openstack'?'RegionOne':'cn-hangzhou'}
function selectProvider(){form.value.provider=provider.value;form.value.endpoint=endpointFor(provider.value);form.value.regionId=regionFor(provider.value);form.value.projectId='';form.value.projectName='';form.value.userDomain='Default';form.value.projectDomain='Default';config.value={configured:false};instances.value=[];schedule.value={enabled:false,intervalMinutes:60,nextSyncAt:'',lastSyncAt:'',lastSyncStatus:'',lastSyncMessage:'',lastSyncCount:0};message.value='';error.value=''}
function cloudBase(){return provider.value==='tencent'?'/api/v1/cmdb/cloud-tencent':provider.value==='aws'?'/api/v1/cmdb/cloud-aws':provider.value==='huawei'?'/api/v1/cmdb/cloud-huawei':provider.value==='openstack'?'/api/v1/cmdb/cloud-openstack':'/api/v1/cmdb/cloud'}
function payload(){return {...form.value,secretId:form.value.accessKeyId,secretKey:form.value.accessKeySecret,authUrl:form.value.endpoint,username:form.value.accessKeyId,password:form.value.accessKeySecret}}
const headers=()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'})
async function api(path:string,init?:RequestInit){const r=await fetch(path,{...init,headers:headers()});const b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.message||'请求失败');return b}
async function loadSchedule(){try{const data=await api('/api/v1/cmdb/cloud-sync/schedules');const item=(data.items||[]).find((entry:any)=>entry.provider===provider.value);if(item)schedule.value={enabled:Boolean(item.autoSyncEnabled),intervalMinutes:item.syncIntervalMinutes||60,nextSyncAt:item.nextSyncAt||'',lastSyncAt:item.lastSyncAt||'',lastSyncStatus:item.lastSyncStatus||'',lastSyncMessage:item.lastSyncMessage||'',lastSyncCount:item.lastSyncCount||0}}catch{}}
async function load(){busy.value=true;error.value='';form.value.provider=provider.value;try{config.value=await api(cloudBase()+'/config');await loadSchedule();if(config.value.configured){const d=await api(cloudBase()+'/inventory');instances.value=d.instances||[];form.value.endpoint=d.endpoint||d.authUrl||config.value.endpoint||config.value.authUrl||endpointFor(provider.value);form.value.regionId=d.regionId||config.value.regionId||regionFor(provider.value);form.value.projectId=config.value.projectId||'';form.value.projectName=config.value.projectName||'';form.value.userDomain=config.value.userDomain||'Default';form.value.projectDomain=config.value.projectDomain||'Default';form.value.accessKeyId=config.value.accessKeyId||config.value.username||''}}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{busy.value=false}}
async function save(){busy.value=true;try{config.value=await api(cloudBase()+'/config',{method:'PUT',body:JSON.stringify(payload())});await api('/api/v1/cmdb/cloud-sync/schedules/'+provider.value,{method:'PUT',body:JSON.stringify(schedule.value)});message.value='连接配置和同步计划已保存';await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
async function test(){busy.value=true;try{await api(cloudBase()+'/config/test',{method:'POST',body:JSON.stringify(payload())});message.value='连接测试通过'}catch(e){error.value=e instanceof Error?e.message:'连接失败'}finally{busy.value=false}}
async function sync(){busy.value=true;try{const r=await api('/api/v1/cmdb/cloud-sync/run/'+provider.value,{method:'POST'});message.value=`已同步 ${r.instances} 个资源`;await load()}catch(e){error.value=e instanceof Error?e.message:'同步失败'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="cloud-panel"><header><div><span>CLOUD RESOURCE SYNC</span><h2>云资源同步</h2><p>阿里云、腾讯云、AWS、华为云和 OpenStack 接入，凭据保存到 Vault。</p></div><div><button @click="showForm=!showForm">配置连接</button><button :disabled="busy" @click="load"><RefreshCw/>刷新</button><button class="primary" :disabled="busy||!config.configured" @click="sync"><Cloud/>同步</button></div></header><p v-if="error" class="error">{{error}}</p><p v-if="message" class="message">{{message}}</p><form v-if="showForm" @submit.prevent="save"><label>云厂商<select v-model="provider" @change="selectProvider"><option value="aliyun">阿里云 ECS</option><option value="tencent">腾讯云 CVM</option><option value="aws">AWS EC2</option><option value="huawei">华为云 ECS</option><option value="openstack">OpenStack Nova</option></select></label><label>接入点 / 认证地址<input v-model="form.endpoint"></label><label>地域<input v-model="form.regionId"></label><label v-if="provider==='huawei'">项目 ID<input v-model="form.projectId"></label><label v-if="provider==='openstack'">项目名称<input v-model="form.projectName"></label><label v-if="provider==='openstack'">用户域<input v-model="form.userDomain"></label><label v-if="provider==='openstack'">项目域<input v-model="form.projectDomain"></label><label>SecretId / AccessKey ID / 用户名<input v-model="form.accessKeyId"></label><label>SecretKey / AccessKey Secret / 密码<input v-model="form.accessKeySecret" type="password"></label><label><input v-model="form.insecure" type="checkbox">跳过TLS校验</label><label><input v-model="form.enabled" type="checkbox">启用同步</label><button type="button" @click="test">测试连接</button><button class="primary" type="submit"><Save/>保存</button></form><div v-if="showForm" class="schedule-form"><strong>自动同步</strong><label>状态<select v-model="schedule.enabled"><option :value="false">关闭</option><option :value="true">启用</option></select></label><label>同步间隔<select v-model="schedule.intervalMinutes"><option :value="5">5 分钟</option><option :value="15">15 分钟</option><option :value="30">30 分钟</option><option :value="60">1 小时</option><option :value="360">6 小时</option><option :value="720">12 小时</option><option :value="1440">1 天</option></select></label><span>启用后按计划自动同步；失败会在下一周期重试，并保留最近执行结果。</span></div><div v-if="config.configured" class="sync-result"><span>最近同步：{{schedule.lastSyncAt||'尚未执行'}}</span><b :class="{failed:schedule.lastSyncStatus==='failed'}">{{schedule.lastSyncStatus||'待执行'}}</b><span>{{schedule.lastSyncMessage||'暂无结果'}} · {{schedule.lastSyncCount}} 个资源</span><span>下次执行：{{schedule.nextSyncAt||'未启用自动同步'}}</span></div><div v-if="config.configured" class="instances"><article v-for="i in instances" :key="i.InstanceID"><div><strong>{{i.Name||i.InstanceID}}</strong><span>{{i.InstanceID}} · {{i.ZoneID}}</span></div><div><b>{{i.Status}}</b><span>{{i.PublicIP||i.PrivateIP}} · {{i.InstanceType}}</span></div></article></div></section></template>
<style scoped>
.cloud-panel{padding:18px;border:1px solid #173b55;border-radius:12px;background:#071925}.cloud-panel>header{display:flex;justify-content:space-between;gap:12px}.cloud-panel header span{color:#22d3ee;font:10px monospace;letter-spacing:.12em}.cloud-panel h2{margin:5px 0}.cloud-panel p{margin:0;color:#7894a8;font-size:11px}.cloud-panel header>div:last-child{display:flex;gap:8px}.cloud-panel button{display:inline-flex;align-items:center;gap:6px;padding:8px 11px;border:1px solid #23455f;background:#0b263b;color:#bdd8e9;border-radius:6px}.cloud-panel button.primary{background:#087b9e}.cloud-panel form{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px;padding:14px;border:1px solid #246c98;background:#061620}.cloud-panel label{display:grid;gap:5px;color:#7894a8;font-size:10px}.cloud-panel label:has(input[type=checkbox]){display:flex;align-items:center}.cloud-panel input{height:34px;border:1px solid #28536c;background:#031525;color:#d5edf8;padding:0 8px}.cloud-panel .error{color:#ff9cad}.cloud-panel .message{color:#a5f3fc}.instances{display:grid;gap:8px;margin-top:12px}.instances article{display:flex;justify-content:space-between;padding:11px;border:1px solid #16445c;background:#061620}.instances strong,.instances span{display:block}.instances span{color:#6f91a5;font-size:10px}.instances b{color:#2dd4bf}
.schedule-form{display:grid;grid-template-columns:120px 1fr 1fr;gap:10px;align-items:end;margin-top:12px;padding:12px;border:1px solid #155e75;background:#061b26}.schedule-form strong{color:#67e8f9;font-size:12px}.schedule-form span{grid-column:1/-1;color:#7894a8;font-size:10px}.schedule-form label{display:grid;gap:4px;color:#7894a8;font-size:10px}.schedule-form select{height:34px;border:1px solid #28536c;background:#031525;color:#d5edf8;padding:0 8px}.sync-result{display:flex;flex-wrap:wrap;gap:8px 18px;align-items:center;margin-top:12px;padding:10px 12px;border:1px solid #16445c;background:#061620;color:#7894a8;font-size:10px}.sync-result b{color:#2dd4bf}.sync-result b.failed{color:#fb7185}.sync-result span:first-child{color:#bdd8e9}.sync-result span:last-child{margin-left:auto}
</style>
